const items = $input.all();
const noContext = 'No se encontró material relevante sobre el tema en la base de datos.';
if (!items.length || !items[0].json) {
  return [{ json: { context: noContext, citations: [] } }];
}

const sources = [];
const seenChunks = new Set();
for (const item of items) {
  const doc = item.json.document || item.json;
  const rawText = doc.pageContent || doc.text || item.json.pageContent || item.json.text || '';
  const text = typeof rawText === 'string' ? rawText.trim() : '';
  const metadata = doc.metadata || item.json.metadata || {};
  const location = metadata.loc && typeof metadata.loc === 'object' ? metadata.loc : {};
  const source = metadata.sourceFile || metadata.archivo || metadata.filename || metadata.source || 'Material del curso';
  const page = metadata.pagina || metadata.page || metadata.pageNumber || location.pageNumber || null;

  if (!text) continue;
  const chunkKey = JSON.stringify([source, page, text]);
  if (seenChunks.has(chunkKey)) continue;
  seenChunks.add(chunkKey);
  sources.push({ text, source, page });
}

if (!sources.length) {
  return [{ json: { context: noContext, citations: [] } }];
}

const citationNumbers = new Map();
const citations = [];
const formattedText = sources.map(function(source) {
  const citationKey = JSON.stringify([source.source, source.page]);
  let citationNumber = citationNumbers.get(citationKey);
  if (!citationNumber) {
    citationNumber = citations.length + 1;
    citationNumbers.set(citationKey, citationNumber);
    citations.push({ archivo: source.source, pagina: source.page });
  }
  const pageInfo = source.page ? ' (Pág. ' + source.page + ')' : '';
  return '[' + citationNumber + '] Fuente: ' + source.source + pageInfo + '\n' + source.text;
}).join('\n\n---\n\n');

return [{ json: { context: formattedText, citations: citations } }];
